// Package logging provides structured logging for the Entire CLI using slog.
//
// Usage:
//
//	// Initialize logger for a session (typically at session start)
//	if err := logging.Init(sessionID); err != nil {
//	    // handle error
//	}
//	defer logging.Close()
//
//	// Add context values
//	ctx = logging.WithComponent(ctx, "hooks")
//	ctx = logging.WithAgent(ctx, agentName)
//
//	// Log with context - component/agent extracted automatically
//	logging.Info(ctx, "hook invoked",
//	    slog.String("hook", hookName),
//	    slog.String("branch", branch),
//	)
package logging

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/validation"
)

// LogLevelEnvVar is the environment variable that controls log level.
const LogLevelEnvVar = "ENTIRE_LOG_LEVEL"

// LogsDir is the directory where log files are stored (relative to repo root).
const LogsDir = ".entire/logs"

var (
	// logger is the package-level logger instance
	logger *slog.Logger

	// logFile holds the current log file handle for cleanup
	logFile *os.File

	// logBufWriter wraps logFile with buffered I/O for performance
	logBufWriter *bufio.Writer

	// currentSessionID stores the session ID from Init() to include in all logs
	currentSessionID string

	// mu protects logger, logFile, logBufWriter, and currentSessionID
	mu sync.RWMutex

	// logLevelGetter is an optional callback to get log level from settings.
	// Set by SetLogLevelGetter before Init is called.
	logLevelGetter func() string
)

// SetLogLevelGetter sets a callback function to get the log level from settings.
// This allows the logging package to read settings without a circular dependency.
// The callback is only used if ENTIRE_LOG_LEVEL env var is not set.
func SetLogLevelGetter(getter func() string) {
	mu.Lock()
	defer mu.Unlock()
	logLevelGetter = getter
}

// Init initializes the logger for a session, writing JSON logs to
// .entire/logs/entire.log.
//
// If sessionID is non-empty, it is stored as an slog attribute on every log line for filtering.
// If the log file cannot be created, falls back to stderr.
// Log level is controlled by ENTIRE_LOG_LEVEL environment variable.
func Init(ctx context.Context, sessionID string) error {
	// Validate session ID if provided (used only for the slog attribute, not the filename)
	if sessionID != "" {
		if err := validation.ValidateSessionID(sessionID); err != nil {
			return fmt.Errorf("invalid session ID for logging: %w", err)
		}
	}

	mu.Lock()
	defer mu.Unlock()

	// Close any existing log file (flush buffer first)
	if logBufWriter != nil {
		_ = logBufWriter.Flush()
		logBufWriter = nil
	}
	if logFile != nil {
		_ = logFile.Close()
		logFile = nil
	}

	// Get log level from environment first, then settings
	levelStr := os.Getenv(LogLevelEnvVar)
	if levelStr == "" && logLevelGetter != nil {
		levelStr = logLevelGetter()
	}
	level := parseLogLevel(levelStr)

	// Warn if invalid level was provided
	if levelStr != "" && !isValidLogLevel(levelStr) {
		fmt.Fprintf(os.Stderr, "[entire] Warning: invalid log level %q, defaulting to INFO\n", levelStr)
	}

	// Determine log file path
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		// Fall back to current directory
		repoRoot = "."
	}

	logsPath := filepath.Join(repoRoot, LogsDir)
	if err := os.MkdirAll(logsPath, 0o750); err != nil {
		// Fall back to stderr
		logger = createLogger(os.Stderr, level)
		return nil
	}

	logFilePath := filepath.Join(logsPath, "entire.log")
	f, err := os.OpenFile(logFilePath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600) //nolint:gosec // fixed filename, not user-controlled
	if err != nil {
		// Fall back to stderr
		logger = createLogger(os.Stderr, level)
		return nil
	}

	logFile = f
	logBufWriter = bufio.NewWriterSize(f, 8192) // 8KB buffer for batched writes
	logger = createLogger(logBufWriter, level)
	currentSessionID = sessionID

	return nil
}

// Logger returns the active *slog.Logger so packages that cannot take a
// context (e.g. redact) can be pointed at the same .entire/logs/ sink.
// Falls back to slog.Default() when Init has not run (or fell back to
// stderr), so callers always get a usable logger. Snapshot semantics:
// call after Init.
func Logger() *slog.Logger {
	mu.RLock()
	defer mu.RUnlock()
	if logger == nil {
		return slog.Default()
	}
	return logger
}

// Close closes the log file if one is open.
// Flushes any buffered data before closing.
// Safe to call multiple times.
func Close() {
	mu.Lock()
	defer mu.Unlock()

	if logBufWriter != nil {
		_ = logBufWriter.Flush()
		logBufWriter = nil

var initRedactionOnce sync.Once

// EnsureRedactionConfigured loads redaction settings and configures the
// redact package: PII detection (opt-in), inline custom_redactions, and rule
// packs auto-discovered from .entire/redactors/.
//
// Must be called at each process entry point before checkpoint writes.
func EnsureRedactionConfigured() {
	initRedactionOnce.Do(func() {
		ctx := context.Background()

		// Route the redact package's diagnostics (pack load failures, rule
		// compile errors, sample mismatches) into .entire/logs/ before any
		// rule loading below can emit them. Without this they go to the
		// process-default stderr logger, which hook contexts swallow.
		redact.SetLogger(logging.Logger())

		s, err := settings.Load(ctx)
		if err != nil {
			logCtx := logging.WithComponent(ctx, "redaction")
			logging.Warn(logCtx, "failed to load settings for redaction", slog.String("error", err.Error()))
			return
		}

		// PII detection (opt-in).
		if s.Redaction != nil && s.Redaction.PII != nil && s.Redaction.PII.Enabled {
			pii := s.Redaction.PII
			cfg := redact.PIIConfig{
				Enabled:        true,
				Categories:     make(map[redact.PIICategory]bool),
				CustomPatterns: pii.CustomPatterns,
			}
			cfg.Categories[redact.PIIEmail] = pii.Email == nil || *pii.Email
			cfg.Categories[redact.PIIPhone] = pii.Phone == nil || *pii.Phone
			cfg.Categories[redact.PIIAddress] = pii.Address != nil && *pii.Address
			redact.ConfigurePII(cfg)
		}

		// Custom rules: inline + packs.
		var inline map[string]string
		if s.Redaction != nil {
			inline = s.Redaction.CustomRedactions
		}
		packsRelPath := filepath.Join(paths.EntireDir, redact.RedactorsDirName)
		packsDir, perr := paths.AbsPath(ctx, packsRelPath)
		if perr != nil {
			logCtx := logging.WithComponent(ctx, "redaction")
			logging.Warn(logCtx, "failed to resolve redactors path", slog.String("error", perr.Error()))
			packsDir = packsRelPath
		}
		packs, lerr := redact.LoadPacks(packsDir)
		if lerr != nil {
			logCtx := logging.WithComponent(ctx, "redaction")
			logging.Warn(logCtx, "failed to load redactor packs", slog.String("error", lerr.Error()))
			// Hooks log to .entire/logs/entire.log, where most users never
			// look. Surface a one-line breadcrumb on stderr when we have a
			// real terminal so the user can find the detail.
			if interactive.IsTerminalWriter(os.Stderr) {
				fmt.Fprintf(os.Stderr, "[entire] redactor packs failed to load (%v); see .entire/logs/entire.log or run `entire doctor`.\n", lerr)
			}
		}
		if len(inline) > 0 || len(packs) > 0 {
			redact.ConfigureCustomRules(redact.CustomRulesConfig{
				Inline: inline,
				Packs:  packs,
			})
		}

		// OpenAI Privacy Filter (opt-in 9th layer).
		opfEnabled := false
		if s.Redaction != nil && s.Redaction.OpenAIPrivacyFilter != nil {
			opf := s.Redaction.OpenAIPrivacyFilter
			redact.ConfigurePrivacyFilter(redact.OPFConfig{
				Enabled:    opf.Enabled,
				Categories: opf.Categories,
				Command:    opf.Command,
				Timeout:    opf.TimeoutSeconds,
			})
			opfEnabled = opf.Enabled
		}

		// Load-time summary so "are my rules active?" is answerable from the
		// log alone — a customer spent days unable to tell whether their
		// packs were loading. One line per process (this runs under a Once).
		packRules := 0
		for _, p := range packs {
			packRules += len(p.Rules)
		}
		piiEnabled := s.Redaction != nil && s.Redaction.PII != nil && s.Redaction.PII.Enabled
		logging.Info(logging.WithComponent(ctx, "redaction"), "redaction configured",
			slog.Int("packs", len(packs)),
			slog.Int("pack_rules", packRules),
			slog.Int("inline_patterns", len(inline)),
			slog.Bool("pii", piiEnabled),
			slog.Bool("opf", opfEnabled),
		)
	})
}

